//#region src/utils/localStorage.ts
function getLocalStorageConfigItem(key) {
	const localStorageBoolean = getLocalStorageBoolean(key);
	if (localStorageBoolean == null) return false;
	return localStorageBoolean;
}
function getLocalStorageBoolean(key) {
	try {
		if (localStorage.getItem(key) === "1") return true;
		else if (localStorage.getItem(key) == null) return null;
		else return false;
	} catch {
		return null;
	}
}
function setLocalStorageBoolean(key, value) {
	try {
		localStorage.setItem(key, value ? "1" : "0");
	} catch {}
}
const deleteLocalStorageItem = (key) => {
	try {
		localStorage.removeItem(key);
	} catch {}
};
